SELECT datetime('now') now_utc;
SELECT status, COUNT(*) n FROM skill_candidates GROUP BY status;
SELECT COALESCE(workspace_root,'(null)') ws, status, COUNT(*) n FROM skill_candidates GROUP BY 1,2 ORDER BY 1,2;
SELECT residency, status, COUNT(*) n FROM skill_candidates GROUP BY 1,2;
SELECT json_array_length(source_session_ids) sessions, status, COUNT(*) n FROM skill_candidates GROUP BY 1,2 ORDER BY 1,2;
SELECT datetime(MIN(created_at)/1000,'unixepoch') first_cand, datetime(MAX(created_at)/1000,'unixepoch') last_cand FROM skill_candidates;
SELECT substr(datetime(created_at/1000,'unixepoch'),1,7) month, status, COUNT(*) n FROM skill_candidates GROUP BY 1,2 ORDER BY 1,2;
SELECT id, name, display_name, description, json_array_length(source_session_ids) nsess, success_count, failure_count, pinned, judge_score, judge_status, replay_confidence, trigger_score, datetime(created_at/1000,'unixepoch') created, datetime(promoted_at/1000,'unixepoch') promoted, body_path, workspace_root FROM skill_candidates WHERE status='promoted';
SELECT substr(COALESCE(rejected_reason,'(null)'),1,60) reason, COUNT(*) n FROM skill_candidates WHERE status='rejected' GROUP BY 1 ORDER BY n DESC LIMIT 25;
SELECT judge_status, COUNT(*) n, ROUND(AVG(judge_score),2) avg_score, MIN(judge_score) mn, MAX(judge_score) mx FROM skill_candidates GROUP BY 1;
SELECT status, CASE WHEN judge_score IS NULL THEN 'null' WHEN judge_score>=8 THEN '>=8' WHEN judge_score>=6 THEN '6-8' ELSE '<6' END band, COUNT(*) n FROM skill_candidates GROUP BY 1,2 ORDER BY 1,2;
SELECT name, display_name, judge_score, datetime(created_at/1000,'unixepoch') created FROM skill_candidates WHERE status='candidate' ORDER BY judge_score DESC LIMIT 15;
SELECT COUNT(*) n_invocations FROM skill_invocations;
SELECT c.name, c.status, COUNT(*) n, SUM(i.succeeded) ok FROM skill_invocations i JOIN skill_candidates c ON c.id=i.skill_id GROUP BY 1,2;
SELECT COUNT(*) n, COUNT(DISTINCT skill_slug) slugs, datetime(MIN(invoked_at)/1000,'unixepoch') first, datetime(MAX(invoked_at)/1000,'unixepoch') last FROM skill_invocation_events;
SELECT source, verdict_source, COUNT(*) n, SUM(succeeded) ok, SUM(is_error) err FROM skill_invocation_events GROUP BY 1,2 ORDER BY n DESC;
SELECT e.skill_slug, COUNT(*) n FROM skill_invocation_events e WHERE e.skill_slug IN (SELECT name FROM skill_candidates WHERE status='promoted') OR e.skill_slug IN (SELECT display_name FROM skill_candidates WHERE status='promoted') GROUP BY 1;
SELECT e.skill_slug, COUNT(*) n FROM skill_invocation_events e WHERE e.skill_slug IN (SELECT name FROM skill_candidates) GROUP BY 1 ORDER BY n DESC LIMIT 20;
SELECT skill_slug, COUNT(*) n, SUM(succeeded) ok, SUM(is_error) err, SUM(CASE WHEN verdict_source IS NULL THEN 1 ELSE 0 END) no_verdict, ROUND(SUM(cost_usd),2) cost, SUM(input_tokens) tin, SUM(output_tokens) tout FROM skill_invocation_events GROUP BY 1 ORDER BY n DESC LIMIT 40;
SELECT kind, clone_status, COUNT(*) n, SUM(CASE WHEN last_enhanced_at IS NOT NULL THEN 1 ELSE 0 END) enhanced FROM skill_registry GROUP BY 1,2;
SELECT kind, slug, clone_status, diverged, history_dir, datetime(last_enhanced_at/1000,'unixepoch') last_enh, candidate_id FROM skill_registry WHERE last_enhanced_at IS NOT NULL OR kind='agent' OR clone_status='synth';
SELECT status, COUNT(*) n, ROUND(AVG(cluster_size),2) avg_cluster, MAX(cluster_size) max_cluster FROM skill_suggestions GROUP BY 1;
SELECT name, cluster_size, judge_score, status, datetime(created_at/1000,'unixepoch') created FROM skill_suggestions ORDER BY created_at DESC LIMIT 15;
SELECT stage, ROUND(SUM(input_tokens)/1e6,3) in_mtok, ROUND(SUM(output_tokens)/1e6,3) out_mtok, ROUND(SUM(cost_usd),2) cost_usd, COUNT(*) days, MIN(day_key) first_day, MAX(day_key) last_day FROM skill_synthesis_budget GROUP BY 1 ORDER BY cost_usd DESC;
SELECT ROUND(SUM(input_tokens)/1e6,3) in_mtok, ROUND(SUM(output_tokens)/1e6,3) out_mtok, ROUND(SUM(cost_usd),2) cost_usd FROM skill_synthesis_budget;
SELECT ROUND(SUM(CASE WHEN day_key>=date('now','-30 day') THEN cost_usd END),2) cost30, ROUND(SUM(CASE WHEN day_key>=date('now','-90 day') THEN cost_usd END),2) cost90, SUM(CASE WHEN day_key>=date('now','-30 day') THEN input_tokens+output_tokens END) tok30, SUM(CASE WHEN day_key>=date('now','-90 day') THEN input_tokens+output_tokens END) tok90 FROM skill_synthesis_budget;
SELECT day_key, stage, input_tokens, output_tokens, ROUND(cost_usd,3) cost FROM skill_synthesis_budget ORDER BY day_key DESC, stage LIMIT 120;
SELECT stage, status, COUNT(*) n FROM skill_synthesis_queue GROUP BY 1,2 ORDER BY 1,2;
SELECT stage, COUNT(*) n, ROUND(SUM(finished_at-claimed_at)/3600000.0,2) wall_h, ROUND(AVG(finished_at-claimed_at)/1000.0,1) avg_s, SUM(attempt_count) attempts FROM skill_synthesis_queue WHERE finished_at IS NOT NULL AND claimed_at IS NOT NULL GROUP BY 1;
SELECT COALESCE(lane,'(null)') lane, stage, COUNT(*) n FROM skill_synthesis_queue GROUP BY 1,2 ORDER BY n DESC LIMIT 30;
SELECT datetime(MIN(enqueued_at)/1000,'unixepoch') first, datetime(MAX(enqueued_at)/1000,'unixepoch') last, COUNT(*) n, COUNT(DISTINCT session_id) sessions FROM skill_synthesis_queue;
SELECT substr(COALESCE(reason,last_error,'(null)'),1,70) r, stage, status, COUNT(*) n FROM skill_synthesis_queue WHERE status IN ('skipped','failed','unscored') GROUP BY 1,2,3 ORDER BY n DESC LIMIT 25;
SELECT date(enqueued_at/1000,'unixepoch') d, stage, COUNT(*) n FROM skill_synthesis_queue WHERE enqueued_at >= (strftime('%s','now','-30 day')*1000) GROUP BY 1,2 ORDER BY 1 DESC,2 LIMIT 150;
SELECT COUNT(*) n, SUM(passes) passes, datetime(MIN(created_at)/1000,'unixepoch') first, datetime(MAX(created_at)/1000,'unixepoch') last FROM skill_session_verdicts;
SELECT evidence_class, COUNT(*) n FROM skill_session_verdicts GROUP BY 1;
SELECT COALESCE(model,'(null)') model, COALESCE(lane,'(null)') lane, COUNT(*) n, SUM(passes) passes FROM skill_session_verdicts GROUP BY 1,2 ORDER BY n DESC LIMIT 20;
SELECT substr(COALESCE(degraded_reason,'(none)'),1,60) r, COUNT(*) n FROM skill_session_verdicts GROUP BY 1 ORDER BY n DESC LIMIT 10;
SELECT id, name, cron_expr, enabled, substr(prompt,1,80) prompt, datetime(last_run_at/1000,'unixepoch') last_run FROM scheduled_jobs;
SELECT j.name, r.status, COUNT(*) n, ROUND(SUM(r.ended_at-r.started_at)/3600000.0,2) wall_h FROM job_runs r JOIN scheduled_jobs j ON j.id=r.job_id GROUP BY 1,2;
SELECT * FROM skill_backlog_purge_state;
SELECT * FROM skill_backlog_cleanup_state;
